def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    own_last, opp_last = history[-1]
    own_prev = history[-2][0] if n > 1 else own_last
    opp_prev = history[-2][1] if n > 1 else 'C'

    opp_d_total = 0
    unprov = 0
    for i in range(n):
        a, b = history[i]
        if b == 'D':
            opp_d_total += 1
            p1 = history[i - 1][0] if i > 0 else 'C'
            p2 = history[i - 2][0] if i > 1 else 'C'
            if p1 == 'C' and p2 == 'C':
                unprov += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    own_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            own_d_streak += 1
        else:
            break

    w = 10 if n > 10 else n
    recent_opp_d = 0
    recent_own_d = 0
    for i in range(n - w, n):
        a, b = history[i]
        if b == 'D':
            recent_opp_d += 1
        if a == 'D':
            recent_own_d += 1

    recent_punish = 0
    recent_forgive = 0
    start = n - 25
    if start < 0:
        start = 0
    for i in range(start, n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C':
            if history[i + 1][1] == 'D':
                recent_punish += 1
            elif history[i + 1][1] == 'C':
                recent_forgive += 1

    if n == 99:
        return 'D'
    if n == 1 and opp_last == 'D':
        return 'D'

    if opp_d_streak >= 4:
        return 'D'
    if unprov >= 3 and recent_opp_d >= 2:
        return 'D'
    if unprov >= 2 and opp_d_total >= 4 and opp_d_streak >= 3:
        return 'D'
    if opp_d_total >= 6 and unprov >= 2 and recent_opp_d >= 2:
        return 'D'
    if unprov >= 2 and recent_opp_d >= 3 and opp_d_total >= 4:
        return 'D'
    if recent_opp_d >= 4 and unprov >= 1 and recent_own_d <= 2:
        return 'D'

    if n <= 2 and unprov == 0:
        return 'C'

    if opp_last == 'D':
        if own_last == 'D':
            if opp_d_streak >= 3 or (opp_d_streak >= 2 and unprov >= 2):
                return 'D'
            if own_prev == 'D' and opp_prev == 'C' and unprov == 0:
                if rng.random() < 0.85:
                    return 'C'
                return 'D'
            if unprov == 0 and recent_opp_d <= 2 and opp_d_streak <= 2:
                if rng.random() < 0.70:
                    return 'C'
                return 'D'
            return 'D'

        if own_prev == 'D':
            if opp_d_streak >= 3 or unprov >= 2:
                return 'D'
            return 'C'

        if unprov >= 3 or recent_opp_d >= 3 or opp_d_streak >= 3:
            return 'D'
        return 'D'

    if own_last == 'D':
        if own_prev == 'C' and opp_prev == 'D':
            if unprov >= 3 or recent_opp_d >= 3 or opp_d_total >= 6:
                return 'D'
            return 'C'

        if own_prev == 'D' and opp_prev == 'C':
            if recent_punish == 0 and unprov == 0 and recent_opp_d == 0:
                if n >= 96 and rng.random() < 0.45:
                    return 'D'
                if own_d_streak <= 2 and recent_forgive == 0 and rng.random() < 0.12:
                    return 'D'
                if recent_forgive > 0 and own_d_streak <= 3:
                    if rng.random() < 0.30:
                        return 'D'
                return 'C'
            return 'C'

        if n >= 97 and recent_punish == 0 and unprov == 0:
            if rng.random() < 0.55:
                return 'D'
        if recent_punish == 0 and unprov == 0 and recent_forgive > 0:
            if rng.random() < 0.18:
                return 'D'
        return 'C'

    if recent_punish == 0 and unprov == 0 and recent_opp_d == 0 and n > 35 and opp_d_total <= 1:
        if n >= 95 and opp_d_total == 0:
            p = 0.40
        elif recent_forgive > 0:
            p = 0.22 if n < 85 else 0.35
        else:
            p = 0.04 if n < 75 else 0.08
        if rng.random() < p:
            return 'D'

    if n == 98 and unprov == 0 and opp_d_total == 0:
        if rng.random() < 0.20:
            return 'D'

    return 'C'
